INSERT INTO feature VALUES('rule-completion','rules','Rule completion','rule-coincidence','implemented','ordinary',NULL,'A block''s critical pair that parts at a non-value is completed by the rule it derives, oriented by the block''s path order and certified by the pair''s two paths; only a join of two values is refused. A `data` block''s derived rules reach the kernel with the written ones. A derived rule that embeds the rule derived from one of its pair''s cells, wrapping it at one point where no held rule rewrites a further wrapping, is refused `RulesNeverComplete` naming both rounds: every round would derive a longer rule.','surface-lowering theory-levitation theory-coherent-resolutions theory-computads','corpus/model/identity/group-laws.gandr corpus/model/desc/rules-completed.gandr corpus/pathological/desc/rules-uncompleted.gandr corpus/pathological/desc/rules-never-complete.gandr','corpus/model/identity/group-laws.gandr',NULL);
